1	import * as fs from "fs";
2	import * as path from "path";
3	import {
4	  loadEnv,
5	  bufferApiQuery,
6	  CREATE_POST_MUTATION,
7	  CHANNEL_IDS,
8	  buildLinkedInInput,
9	  buildMastodonInput,
10	  buildBlueskyInput,
11	  validateCharacterLimits,
12	  validateNoLinkInComments,
13	  addUtmParamsToText,
14	  addUtmParamsToParts,
15	  PostContent,
16	  CreatePostInput,
17	  NetworkType,
18	} from "./bufferPost";
19	import { findNextSlot } from "./slotAllocator";
20	
21	// ============================================================================
22	// Batch Input
23	// ============================================================================
24	
25	/**
26	 * One content piece across the three networks.
27	 *
28	 * `mastodon`/`bluesky` accept either a single string (one post) or an array of
29	 * strings (a thread: `parts[0]` is the root, the rest are replies). Threading
30	 * exists so a network with a tight limit — Bluesky at 290 — can carry the
31	 * message in the root post and the link in a reply instead of having to
32	 * condense the message until content + link fit together.
33	 */
34	export interface BatchEntry {
35	  linkedin: string;
36	  mastodon: string | string[];
37	  bluesky: string | string[];
38	  url?: string;
39	  image?: string;
40	}
41	
42	/** Normalize a single-string or multi-part network field to parts. */
43	function toParts(value: string | string[]): string[] {
44	  return Array.isArray(value) ? value : [value];
45	}
46	
47	interface ScheduleState {
48	  scheduledSlots: string[];
49	}
50	
51	const EVERGREEN_DIR = path.resolve("analytics/social-media-content-evergreen");
52	const STATE_FILE = path.join(EVERGREEN_DIR, ".schedule-state.json");
53	
54	function isNonEmptyString(value: unknown): value is string {
55	  return typeof value === "string" && value.trim() !== "";
56	}
57	
58	/**
59	 * Shape-check one batch entry. Returns a list of problems (empty when valid).
60	 */
61	export function validateBatchEntry(entry: unknown): string[] {
62	  const problems: string[] = [];
63	  if (typeof entry !== "object" || entry === null) {
64	    return ["entry must be an object"];
65	  }
66	  const e = entry as Record<string, unknown>;
67	
68	  if (!isNonEmptyString(e.linkedin)) {
69	    problems.push("`linkedin` must be a non-empty string");
70	  }
71	  for (const field of ["mastodon", "bluesky"] as const) {
72	    const value = e[field];
73	    const parts = Array.isArray(value) ? value : [value];
74	    if (parts.length === 0 || !parts.every(isNonEmptyString)) {
75	      problems.push(
76	        `\`${field}\` must be a non-empty string, or an array of non-empty strings (thread parts)`,
77	      );
78	    }
79	  }
80	  return problems;
81	}
82	
83	function readBatchFile(filePath: string): BatchEntry[] {
84	  if (!fs.existsSync(filePath)) {
85	    console.error(`Batch file not found: ${filePath}`);
86	    process.exit(1);
87	  }
88	  const raw = fs.readFileSync(filePath, "utf-8");
89	  const data = JSON.parse(raw);
90	  if (!Array.isArray(data)) {
91	    console.error(`Batch file must contain a JSON array, got ${typeof data}`);
92	    process.exit(1);
93	  }
94	  for (const [i, entry] of data.entries()) {
95	    const problems = validateBatchEntry(entry);
96	    if (problems.length > 0) {
97	      console.error(`Entry ${i + 1} is malformed:`);
98	      for (const problem of problems) console.error(`  • ${problem}`);
99	      process.exit(1);
100	    }
101	  }
102	  return data;
103	}
104	
105	function readScheduleState(): ScheduleState {
106	  if (!fs.existsSync(STATE_FILE)) {
107	    return { scheduledSlots: [] };
108	  }
109	  return JSON.parse(fs.readFileSync(STATE_FILE, "utf-8")) as ScheduleState;
110	}
111	
112	function writeScheduleState(state: ScheduleState): void {
113	  if (!fs.existsSync(EVERGREEN_DIR)) {
114	    fs.mkdirSync(EVERGREEN_DIR, { recursive: true });
115	  }
116	  fs.writeFileSync(
117	    STATE_FILE,
118	    JSON.stringify(state, null, 2) + "\n",
119	    "utf-8",
120	  );
121	}
122	
123	// ============================================================================
124	// Per-entry preparation
125	// ============================================================================
126	
127	const URL_TEST = /https?:\/\//;
128	
129	export interface PreparedEntry {
130	  content: PostContent;
131	  errors: string[];
132	}
133	
134	export function prepareContent(entry: BatchEntry): PreparedEntry {
135	  const errors: string[] = [];
136	  const url = entry.url?.trim() || null;
137	
138	  // Apply UTM to body text first (in case there are inline agilepainrelief.com URLs)
139	  const linkedinParts = addUtmParamsToParts([entry.linkedin], "LinkedIn");
140	  const mastodonParts = addUtmParamsToParts(toParts(entry.mastodon), "Mastodon");
141	  const blueskyParts = addUtmParamsToParts(toParts(entry.bluesky), "Bluesky");
142	
143	  // Compose final post content. When the `url` field is set and a platform has
144	  // no inline URL, append the link to that platform's LAST part — the post
145	  // itself for a single-part entry, the final reply for a thread. The link
146	  // lives in the body on every platform, LinkedIn included (no first comment).
147	  function withLink(network: NetworkType, parts: string[]): string[] {
148	    if (!url) return parts;
149	    // Conflict check: url field AND an inline URL in any of this platform's parts
150	    if (parts.some((part) => URL_TEST.test(part))) {
151	      errors.push(
152	        `${network} body contains an inline URL AND \`url\` field is set — choose one`,
153	      );
154	      return parts;
155	    }
156	    const link = addUtmParamsToText(url, network);
157	    const last = parts.length - 1;
158	    return parts.map((part, i) => (i === last ? part + "\n\n" + link : part));
159	  }
160	
161	  return {
162	    content: {
163	      linkedin: withLink("LinkedIn", linkedinParts)[0],
164	      mastodon: withLink("Mastodon", mastodonParts),
165	      bluesky: withLink("Bluesky", blueskyParts),
166	    },
167	    errors,
168	  };
169	}
170	
171	function resolveCoverImage(entry: BatchEntry): string | null {
172	  // Only use an image if one is explicitly provided in the JSON. We don't
173	  // auto-fetch og:image any more because Buffer's dedup matches shared
174	  // image assets across posts that point at the same source page.
175	  return entry.image && entry.image.trim() !== "" ? entry.image : null;
176	}
177	
178	// ============================================================================
179	// Pre-flight validation (hard halt on any error)
180	// ============================================================================
181	
182	function snippet(entry: BatchEntry): string {
183	  const text = entry.linkedin.replace(/\s+/g, " ").trim();
184	  return text.length > 30 ? text.slice(0, 30) + "…" : text;
185	}
186	
187	interface PreflightIssue {
188	  index: number;
189	  snippet: string;
190	  message: string;
191	}
192	
193	function preflight(entries: BatchEntry[]): PreflightIssue[] {
194	  const issues: PreflightIssue[] = [];
195	  for (const [i, entry] of entries.entries()) {
196	    const tag = snippet(entry);
197	    const { content, errors: prepErrors } = prepareContent(entry);
198	    for (const msg of prepErrors) {
199	      issues.push({ index: i + 1, snippet: tag, message: msg });
200	    }
201	    for (const err of validateCharacterLimits(content)) {
202	      issues.push({
203	        index: i + 1,
204	        snippet: tag,
205	        message: `${err.network} over ${err.limit} chars (got ${err.effectiveLength} after per-network URL counting)`,
206	      });
207	    }
208	    for (const msg of validateNoLinkInComments(content)) {
209	      issues.push({ index: i + 1, snippet: tag, message: msg });
210	    }
211	  }
212	  return issues;
213	}
214	
215	// ============================================================================
216	// Main
217	// ============================================================================
218	
219	interface CliArgs {
220	  file: string;
221	  dryRun: boolean;
222	  noProbe: boolean;
223	  occupied: string[];
224	}
225	
226	function parseArgs(): CliArgs {
227	  const args = process.argv.slice(2);
228	  const dryRun = args.includes("--dry-run");
229	  const noProbe = args.includes("--no-probe");
230	  const fileIdx = args.indexOf("--file");
231	  if (fileIdx === -1 || !args[fileIdx + 1]) {
232	    console.error(
233	      "Usage: npm run batch -- --file <path-to-json> [--dry-run] [--no-probe] [--occupied <iso> ...]",
234	    );
235	    process.exit(1);
236	  }
237	  const occupied: string[] = [];
238	  const occIdx = args.indexOf("--occupied");
239	  if (occIdx !== -1) {
240	    for (let i = occIdx + 1; i < args.length; i++) {
241	      if (args[i].startsWith("--")) break;
242	      occupied.push(args[i]);
243	    }
244	  }
245	  return { file: path.resolve(args[fileIdx + 1]), dryRun, noProbe, occupied };
246	}
247	
248	// ============================================================================
249	// Buffer probe — query scheduled posts so we know what slots are taken
250	// ============================================================================
251	
252	const ORG_QUERY = `query { account { organizations { id } } }`;
253	
254	const SCHEDULED_POSTS_QUERY = `
255	query ScheduledPosts(
256	  $organizationId: OrganizationId!,
257	  $channelIds: [ChannelId!]!
258	) {
259	  posts(
260	    input: {
261	      organizationId: $organizationId,
262	      filter: { channelIds: $channelIds, status: [scheduled] }
263	    },
264	    first: 100
265	  ) {
266	    edges {
267	      node {
268	        id
269	        dueAt
270	        status
271	        channelId
272	      }
273	    }
274	  }
275	}`;
276	
277	async function fetchOrganizationId(): Promise<string> {
278	  const result = await bufferApiQuery<{
279	    account?: { organizations?: Array<{ id: string }> };
280	  }>(ORG_QUERY);
281	  if (result.errors) {
282	    throw new Error(
283	      `Could not fetch organization id: ${result.errors.map((e) => e.message).join("; ")}`,
284	    );
285	  }
286	  const orgId = result.data?.account?.organizations?.[0]?.id;
287	  if (!orgId) throw new Error("No organization id on this Buffer account");
288	  return orgId;
289	}
290	
291	async function probeOccupiedSlots(): Promise<string[]> {
292	  const organizationId = await fetchOrganizationId();
293	  const channelIds = (
294	    ["LinkedIn", "Mastodon", "Bluesky"] as NetworkType[]
295	  ).map((n) => CHANNEL_IDS[n]);
296	
297	  const result = await bufferApiQuery<{
298	    posts?: {
299	      edges?: Array<{
300	        node?: { dueAt?: string; channelId?: string };
301	      }>;
302	    };
303	  }>(SCHEDULED_POSTS_QUERY, { organizationId, channelIds });
304	
305	  if (result.errors) {
306	    throw new Error(
307	      `Buffer probe failed: ${result.errors.map((e) => e.message).join("; ")}`,
308	    );
309	  }
310	
311	  const edges = result.data?.posts?.edges || [];
312	  const byChannel: Record<string, string[]> = {};
313	  for (const edge of edges) {
314	    const dueAt = edge.node?.dueAt;
315	    const channelId = edge.node?.channelId;
316	    if (!dueAt || !channelId) continue;
317	    (byChannel[channelId] ||= []).push(dueAt);
318	  }
319	  for (const [network, channelId] of Object.entries(CHANNEL_IDS)) {
320	    console.log(`  ${network}: ${(byChannel[channelId] || []).length} scheduled post(s)`);
321	  }
322	  return edges
323	    .map((e) => e.node?.dueAt)
324	    .filter((d): d is string => typeof d === "string");
325	}
326	
327	// Thrown when Buffer rejects a per-post create (e.g. duplicate detection,
328	// content policy). Distinct from systemic errors (network, auth, GraphQL)
329	// which still abort the batch.
330	class BufferRejectionError extends Error {
331	  constructor(
332	    public network: string,
333	    public bufferMessage: string,
334	  ) {
335	    super(`${network} createPost failed: ${bufferMessage}`);
336	  }
337	}
338	
339	async function scheduleOne(
340	  entry: BatchEntry,
341	  index: number,
342	  dueAt: string,
343	  dryRun: boolean,
344	): Promise<void> {
345	  const { content } = prepareContent(entry);
346	  const coverImageUrl = resolveCoverImage(entry);
347	
348	  const mode = "customScheduled" as const;
349	  const inputs: [string, CreatePostInput][] = [
350	    [
351	      "LinkedIn",
352	      { ...buildLinkedInInput(content, coverImageUrl, mode), dueAt },
353	    ],
354	    [
355	      "Mastodon",
356	      { ...buildMastodonInput(content, coverImageUrl, mode), dueAt },
357	    ],
358	    ["Bluesky", { ...buildBlueskyInput(content, coverImageUrl, mode), dueAt }],
359	  ];
360	
361	  if (dryRun) {
362	    console.log(`  [post ${index + 1}] dry-run payloads for ${dueAt}:`);
363	    for (const [name, input] of inputs) {
364	      console.log(`    --- ${name} ---`);
365	      console.log(JSON.stringify(input, null, 2).replace(/^/gm, "    "));
366	    }
367	    return;
368	  }
369	
370	  for (const [name, input] of inputs) {
371	    const result = await bufferApiQuery(CREATE_POST_MUTATION, { input });
372	
373	    if (result.errors) {
374	      const messages = result.errors.map((e) => e.message).join("; ");
375	      throw new Error(`${name} GraphQL error: ${messages}`);
376	    }
377	
378	    const data = result.data as {
379	      createPost:
380	        | { post: { id: string; text: string; status: string; dueAt: string } }
381	        | { message: string };
382	    };
383	
384	    if ("message" in data.createPost) {
385	      throw new BufferRejectionError(name, data.createPost.message);
386	    }
387	    console.log(
388	      `  [post ${index + 1}] ${name} scheduled (id: ${data.createPost.post.id}) for ${dueAt}`,
389	    );
390	  }
391	}
392	
393	async function main(): Promise<void> {
394	  const { file, dryRun, noProbe, occupied } = parseArgs();
395	  loadEnv();
396	
397	  console.log(`Reading batch file: ${file}`);
398	  const entries = readBatchFile(file);
399	  console.log(`Loaded ${entries.length} post(s).`);
400	
401	  console.log("\nPre-flighting entries...");
402	  const issues = preflight(entries);
403	  if (issues.length > 0) {
404	    console.error(`\n${issues.length} validation error(s). NOT posting:`);
405	    for (const issue of issues) {
406	      console.error(
407	        `  • post ${issue.index} ("${issue.snippet}") — ${issue.message}`,
408	      );
409	    }
410	    console.error("\nFix the JSON file and re-run.");
411	    process.exit(1);
412	  }
413	  console.log("  All entries passed pre-flight.");
414	
415	  let probedSlots: string[] = [];
416	  if (!noProbe) {
417	    console.log("\nProbing Buffer for scheduled posts...");
418	    probedSlots = await probeOccupiedSlots();
419	    console.log(`  Total occupied slots discovered: ${probedSlots.length}`);
420	  } else {
421	    console.log("\nSkipping Buffer probe (--no-probe).");
422	  }
423	
424	  const state = readScheduleState();
425	  const sessionSlots: string[] = [];
426	  // State file is kept as a cache but Buffer's probe is the source of truth.
427	  // Manual --occupied overrides are also merged in.
428	  const baselineUsed = noProbe
429	    ? [...state.scheduledSlots, ...occupied]
430	    : [...probedSlots, ...occupied];
431	  const skipped: Array<{ index: number; reason: string; snippet: string }> = [];
432	
433	  console.log("\n" + "=".repeat(60));
434	  console.log(
435	    dryRun
436	      ? "DRY RUN — Computing slots and previewing payloads"
437	      : "Scheduling posts via Buffer API",
438	  );
439	  console.log("=".repeat(60));
440	
441	  for (const [i, entry] of entries.entries()) {
442	    const usedSlots = [...baselineUsed, ...sessionSlots];
443	    const dueAt = findNextSlot(new Date(), usedSlots);
444	    console.log(`\nPost ${i + 1}/${entries.length} → ${dueAt}`);
445	
446	    try {
447	      await scheduleOne(entry, i, dueAt, dryRun);
448	    } catch (err) {
449	      if (err instanceof BufferRejectionError) {
450	        const tag = snippet(entry);
451	        console.error(
452	          `  SKIPPED post ${i + 1} ("${tag}") — ${err.network}: ${err.bufferMessage}`,
453	        );
454	        skipped.push({ index: i + 1, reason: err.message, snippet: tag });
455	        // Slot was attempted; some platforms may have succeeded before the
456	        // rejection. Mark it consumed so the next post moves to a fresh slot.
457	        sessionSlots.push(dueAt);
458	        if (!dryRun) {
459	          state.scheduledSlots.push(dueAt);
460	          writeScheduleState(state);
461	        }
462	        continue;
463	      }
464	      console.error(`\nFAILED on post ${i + 1}: ${err}`);
465	      console.error(
466	        `Stopping. ${i - skipped.length} post(s) scheduled, ${skipped.length} skipped, ${entries.length - i} remaining.`,
467	      );
468	      if (!dryRun && sessionSlots.length > 0) {
469	        state.scheduledSlots.push(...sessionSlots);
470	        writeScheduleState(state);
471	        console.error(
472	          `State file updated with ${sessionSlots.length} slot(s) used in this session.`,
473	        );
474	      }
475	      process.exit(1);
476	    }
477	
478	    sessionSlots.push(dueAt);
479	
480	    if (!dryRun) {
481	      state.scheduledSlots.push(dueAt);
482	      writeScheduleState(state);
483	    }
484	  }
485	
486	  console.log("\n" + "=".repeat(60));
487	  const succeeded = entries.length - skipped.length;
488	  if (dryRun) {
489	    console.log(`Dry run complete. ${entries.length} slot(s) computed, nothing posted.`);
490	  } else {
491	    console.log(`Batch complete. ${succeeded} scheduled, ${skipped.length} skipped.`);
492	  }
493	  if (skipped.length > 0) {
494	    console.log("\nSkipped posts (Buffer rejected, batch continued):");
495	    for (const s of skipped) {
496	      console.log(`  • post ${s.index} ("${s.snippet}") — ${s.reason}`);
497	    }
498	  }
499	  console.log("=".repeat(60));
500	}
501	
502	if (import.meta.url === `file://${process.argv[1]}`) {
503	  main().catch((err) => {
504	    console.error(err);
505	    process.exit(1);
506	  });
507	}
