// Single source of truth for the evergreen posting cadence.
//
// This plain-JS module is imported by BOTH the TypeScript scheduler
// (slotAllocator.ts) and the plain-.mjs calendar audit (calendarAudit.mjs)
// with no build step, so the "posts/weekday" figure the audit prints in the
// calendar header can never drift from what the scheduler actually does.
//
// Each entry is one posting slot per weekday, in Eastern Time (America/New_York).
// The array length IS the posts-per-weekday cadence.

export const DEFAULT_SLOT_PLAN = [
  { hour: 10, minute: 0 },
  { hour: 13, minute: 30 },
];
