  | "marked" // was unposted, now marked with this date
  | "reshared" // already posted before, this date appended
  | "unchanged" // already carries this exact date (re-run of the same batch)
  | "not-found" // no matching line/block
  | "ambiguous"; // more than one match — refuse to guess

export interface MarkResult {
  markdown: string;
  outcome: MarkOutcome;
}

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

function assertIsoDate(date: string): void {
  if (!ISO_DATE.test(date)) {
    throw new Error(`date must be YYYY-MM-DD, got "${date}"`);
  }
}

// ============================================================================
// URLs -> queue slugs
// ============================================================================

const APR_CONTENT_URL =
  /agilepainrelief\.com\/(blog|glossary|quiz)\/([a-z0-9_-]+)/i;

/**
 * The `collection/slug` a url points at, e.g. `blog/feature-factory`, or null
 * when the url isn't an agilepainrelief.com content page. Query strings (the
 * per-network UTM the pipeline appends) and trailing slashes are ignored.
 */
export function contentPathFromUrl(url: string): string | null {
  const m = APR_CONTENT_URL.exec(url);
  if (!m) return null;
  return `${m[1].toLowerCase()}/${m[2].toLowerCase()}`;
}

// ============================================================================
// Posted-date markers
// ============================================================================

/**
 * A parsed posted-date marker.
 *
 * Dates are explicit; `legacyCount` carries forward the older `Nx` shorthand
 * (e.g. `(2025-08-15, 3x)`) that records reshares whose dates were never
 * written down. Total reshares = dates.length + legacyCount.
 */
export interface PostedMarker {
  dates: string[];
  legacyCount: number;
}

const LEGACY_COUNT = /^(\d+)x$/i;

export function parsePostedMarker(text: string): PostedMarker {
  const dates: string[] = [];
  let legacyCount = 0;
  for (const raw of text.split(",")) {
    const token = raw.trim();
    if (ISO_DATE.test(token)) {
      dates.push(token);
      continue;
    }
    const legacy = LEGACY_COUNT.exec(token);
    if (legacy) {
      // `3x` means three postings total, one of which is the date beside it.
      legacyCount += Number(legacy[1]) - 1;
    }
  }
  return { dates, legacyCount };
}

export function formatPostedMarker(marker: PostedMarker): string {
  const parts = [...marker.dates];
  if (marker.legacyCount > 0) parts.push(`${marker.legacyCount + 1}x`);
  return parts.join(", ");
}

/** How many times a marker says the item has been posted. */
export function postedCount(marker: PostedMarker): number {
  return marker.dates.length + marker.legacyCount;
}

/** Append `date` unless it is already recorded. */
function withDate(marker: PostedMarker, date: string): PostedMarker | null {
  if (marker.dates.includes(date)) return null;
  return { ...marker, dates: [...marker.dates, date] };
}

// ============================================================================
// Calendar queue
// ============================================================================

// `- [ ] Title` / `- [x] Title (2025-08-15, 3x)` followed by the url.
const QUEUE_LINE = /^(\s*-\s*\[)( |x|X)(\]\s*)(.*)$/;
const TRAILING_MARKER = /^(.*?)\s*\(([^()]*)\)\s*$/;

interface QueueLine {
  posted: boolean;
  title: string;
  marker: PostedMarker;
  url: string;
}

/**
 * Split a queue line into its parts. The title may carry a trailing
 * `(dates)` marker, and the url is whatever follows the title.
 */
function parseQueueLine(line: string): QueueLine | null {
  const m = QUEUE_LINE.exec(line);
  if (!m) return null;
  const [, , box, , rest] = m;

  // The url is the last whitespace-delimited token that looks like one.
  const urlMatch = /(https?:\/\/\S+)\s*$/.exec(rest);
  if (!urlMatch) return null;
  const url = urlMatch[1];
  let title = rest.slice(0, urlMatch.index).trim();

  let marker: PostedMarker = { dates: [], legacyCount: 0 };
  const trailing = TRAILING_MARKER.exec(title);
  if (trailing) {
    const parsed = parsePostedMarker(trailing[2]);
    // Only treat the parenthetical as a marker if it actually holds dates or a
    // count — titles legitimately contain parentheses.
    if (parsed.dates.length > 0 || parsed.legacyCount > 0) {
      title = trailing[1].trim();
      marker = parsed;
    }
  }

  return {
    posted: box.toLowerCase() === "x",
    title,
    marker,
    url,
  };
}

function renderQueueLine(line: string, parsed: QueueLine): string {
  const leading = /^\s*/.exec(line)![0];
  const markerText = formatPostedMarker(parsed.marker);
  const title = markerText ? `${parsed.title} (${markerText})` : parsed.title;
  return `${leading}- [${parsed.posted ? "x" : " "}] ${title} ${parsed.url}`;
}

/**
 * Mark the queue item whose url points at `contentPath` as posted on `date`.
 *
 * Matching is by `collection/slug`, so the UTM the pipeline appends and any
 * http/https or trailing-slash difference between the batch entry and the
 * queue line are all irrelevant.
 */
export function markCalendarItem(
  markdown: string,
  contentPath: string,
  date: string,
): MarkResult {
  assertIsoDate(date);
  const lines = markdown.split("\n");

  const hits: number[] = [];
  const parsedByIndex = new Map<number, QueueLine>();
  for (const [i, line] of lines.entries()) {
    const parsed = parseQueueLine(line);
    if (!parsed) continue;
    if (contentPathFromUrl(parsed.url) !== contentPath) continue;
    hits.push(i);
    parsedByIndex.set(i, parsed);
  }

  if (hits.length === 0) return { markdown, outcome: "not-found" };
  if (hits.length > 1) return { markdown, outcome: "ambiguous" };

  const index = hits[0];
  const parsed = parsedByIndex.get(index)!;
  const wasPosted = parsed.posted || postedCount(parsed.marker) > 0;

  const updated = withDate(parsed.marker, date);
  if (!updated) return { markdown, outcome: "unchanged" };

  lines[index] = renderQueueLine(lines[index], {
    ...parsed,
    posted: true,
    marker: updated,
  });
  return {
    markdown: lines.join("\n"),
    outcome: wasPosted ? "reshared" : "marked",
  };
