import { describe, it, expect } from "vitest";
import {
  contentPathFromUrl,
  parsePostedMarker,
  formatPostedMarker,
  postedCount,
  markCalendarItem,
  markQuizSeed,
} from "./sourceMarking";

describe("contentPathFromUrl", () => {
  it("extracts collection/slug", () => {
    expect(
      contentPathFromUrl("https://agilepainrelief.com/blog/feature-factory/"),
    ).toBe("blog/feature-factory");
    expect(
      contentPathFromUrl("https://agilepainrelief.com/glossary/systems-thinking/"),
    ).toBe("glossary/systems-thinking");
  });

  it("ignores the UTM the pipeline appends", () => {
    expect(
      contentPathFromUrl(
        "https://agilepainrelief.com/blog/feature-factory/?utm_source=bluesky&utm_campaign=archive-reshare",
      ),
    ).toBe("blog/feature-factory");
  });

  it("returns null for off-site and non-content urls", () => {
    expect(contentPathFromUrl("https://example.com/blog/foo/")).toBeNull();
    expect(contentPathFromUrl("https://agilepainrelief.com/about/")).toBeNull();
  });
});

describe("posted markers", () => {
  it("round-trips a single date", () => {
    const m = parsePostedMarker("2026-07-14");
    expect(m).toEqual({ dates: ["2026-07-14"], legacyCount: 0 });
    expect(formatPostedMarker(m)).toBe("2026-07-14");
    expect(postedCount(m)).toBe(1);
  });

  it("carries the legacy Nx shorthand forward", () => {
    // `(2025-08-15, 3x)` means three postings, only one of them dated.
    const m = parsePostedMarker("2025-08-15, 3x");
    expect(m).toEqual({ dates: ["2025-08-15"], legacyCount: 2 });
    expect(postedCount(m)).toBe(3);
    expect(formatPostedMarker(m)).toBe("2025-08-15, 3x");
  });

  it("counts multiple explicit dates", () => {
    const m = parsePostedMarker("2025-08-15, 2026-01-02");
    expect(postedCount(m)).toBe(2);
  });
});

describe("markCalendarItem", () => {
  const calendar = [
    "### TIER 1",
    "",
    "- [ ] Human-Powered AI Simulation https://agilepainrelief.com/blog/human-powered-ai/",
    "- [x] Feature Factory (2026-05-29) https://agilepainrelief.com/glossary/feature-factory/",
    "- [x] Recommended Books (2025-08-15, 3x) https://agilepainrelief.com/blog/recommended-books/",
    "",
  ].join("\n");

  it("checks off an unposted item and stamps the date", () => {
    const r = markCalendarItem(calendar, "blog/human-powered-ai", "2026-07-27");
    expect(r.outcome).toBe("marked");
    expect(r.markdown).toContain(
      "- [x] Human-Powered AI Simulation (2026-07-27) https://agilepainrelief.com/blog/human-powered-ai/",
    );
  });

  it("leaves every other line untouched", () => {
    const r = markCalendarItem(calendar, "blog/human-powered-ai", "2026-07-27");
    const before = calendar.split("\n");
    const after = r.markdown.split("\n");
    expect(after.length).toBe(before.length);
    for (const i of [0, 1, 3, 4, 5]) expect(after[i]).toBe(before[i]);
  });

  it("appends a reshare date to an already-posted item", () => {
    const r = markCalendarItem(calendar, "glossary/feature-factory", "2026-07-27");
    expect(r.outcome).toBe("reshared");
    expect(r.markdown).toContain("Feature Factory (2026-05-29, 2026-07-27)");
  });

  it("preserves the legacy Nx count when appending", () => {
    const r = markCalendarItem(calendar, "blog/recommended-books", "2026-07-27");
    expect(r.outcome).toBe("reshared");
    expect(r.markdown).toContain(
      "Recommended Books (2025-08-15, 2026-07-27, 3x)",
    );
  });

  it("is idempotent — re-running the same batch changes nothing", () => {
    const once = markCalendarItem(calendar, "blog/human-powered-ai", "2026-07-27");
    const twice = markCalendarItem(
      once.markdown,
      "blog/human-powered-ai",
      "2026-07-27",
    );
    expect(twice.outcome).toBe("unchanged");
    expect(twice.markdown).toBe(once.markdown);
  });

  it("reports a miss rather than editing something else", () => {
    const r = markCalendarItem(calendar, "blog/not-in-the-queue", "2026-07-27");
    expect(r.outcome).toBe("not-found");
    expect(r.markdown).toBe(calendar);
  });

  it("refuses to guess when the slug appears twice", () => {
    const dupe =
      calendar +
      "\n- [ ] Duplicate entry https://agilepainrelief.com/blog/human-powered-ai/";
    const r = markCalendarItem(dupe, "blog/human-powered-ai", "2026-07-27");
    expect(r.outcome).toBe("ambiguous");
    expect(r.markdown).toBe(dupe);
  });

  it("does not mistake parentheses in a title for a date marker", () => {
    const md =
      "- [ ] Scrum (and Kanban) Basics https://agilepainrelief.com/blog/scrum-basics/";
    const r = markCalendarItem(md, "blog/scrum-basics", "2026-07-27");
    expect(r.markdown).toContain(
      "- [x] Scrum (and Kanban) Basics (2026-07-27) https://agilepainrelief.com/blog/scrum-basics/",
    );
  });

  it("rejects a malformed date instead of writing it", () => {
    expect(() =>
      markCalendarItem(calendar, "blog/human-powered-ai", "27-07-2026"),
    ).toThrow();
  });
});

describe("markQuizSeed", () => {
  const seeds = [
    "",
    "[POSTED 2026-05-29]",
    "Senior devs felt 20% faster using AI. METR measured them at 19% slower.",
    "",
    "Twelve questions, three minutes:",
    "-",
    "Security defects in AI-authored code: roughly 1.57x the rate of human-authored.",
    "",
    "Models trained on the public internet. Vulnerabilities and all:",
    "-",
    "GitClear report - Copy-pasted lines now exceed moved lines.",
    "",
    "Code is cheap to generate. Refactoring isn't:",
    "-",
  ].join("\n");

  it("prepends a marker to an unposted block", () => {
    const r = markQuizSeed(seeds, "Security defects in AI-authored code", "2026-07-27");
    expect(r.outcome).toBe("marked");
    expect(r.markdown).toContain(
      "[POSTED 2026-07-27]\nSecurity defects in AI-authored code",
    );
  });

  it("does not disturb the other blocks or the separators", () => {
    const r = markQuizSeed(seeds, "Security defects in AI-authored code", "2026-07-27");
