// ============================================================================
// Source marking — keep the content queues honest
// ============================================================================

const PLANNING_DIR = path.resolve("social-media/planning");
const CALENDAR_FILE = path.join(
  PLANNING_DIR,
  "complete-social-media-calendar.md",
);
const QUIZ_SEED_FILE = path.join(
  PLANNING_DIR,
  "AI Failure Modes Quiz Generated Posts.md",
);

/**
 * Marks the calendar entry and/or quiz seed behind a post, immediately after
 * Buffer accepts it. Writing straight after each success (rather than batching
 * the edits to the end) means a crash mid-run leaves the ledger matching what
 * is actually queued.
 *
 * Marking never aborts the batch: the posts are already scheduled by the time
 * we get here, so a bookkeeping failure is reported and carried to the summary
 * rather than thrown.
 */
class SourceMarker {
  readonly notes: string[] = [];

  constructor(private readonly enabled: boolean) {}

  private applyToFile(
    file: string,
    label: string,
    apply: (markdown: string) => MarkResult,
    what: string,
  ): void {
    if (!fs.existsSync(file)) {
      this.notes.push(
        `${what}: ${label} not found at ${file} (run from the Astro repo root to enable marking)`,
      );
      return;
    }
    const before = fs.readFileSync(file, "utf-8");
    const { markdown, outcome } = apply(before);
    if (outcome === "marked" || outcome === "reshared") {
      fs.writeFileSync(file, markdown, "utf-8");
      console.log(`    ${label} ${outcome}: ${what}`);
      return;
    }
    this.notes.push(`${what}: ${label} ${outcome}`);
  }

  mark(entry: BatchEntry, date: string): void {
    if (!this.enabled) return;

    const contentPath = entry.url ? contentPathFromUrl(entry.url) : null;
    // Only blog and glossary items live in the calendar queue; the quiz page is
    // promoted from seed blocks instead.
    if (contentPath && !contentPath.startsWith("quiz/")) {
      this.applyToFile(
        CALENDAR_FILE,
        "calendar",
        (md) => markCalendarItem(md, contentPath, date),
        contentPath,
      );
    }

    if (entry.seed) {
      this.applyToFile(
        QUIZ_SEED_FILE,
        "quiz seed",
        (md) => markQuizSeed(md, entry.seed!, date),
        `"${entry.seed.slice(0, 40)}…"`,
      );
    }
  }
}

/** ET calendar date for a slot, which is what the queues record. */
export function slotDate(dueAt: string): string {
  return new Intl.DateTimeFormat("en-CA", {
    timeZone: "America/New_York",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(new Date(dueAt));
}

// ============================================================================
// Main
// ============================================================================

interface CliArgs {
  file: string;
  dryRun: boolean;
  noProbe: boolean;
  noMark: boolean;
  occupied: string[];
}

