input.content:
// Measure how the reshare queue is actually performing.
//
// The quarterly queue tune used to ask an assistant to write a throwaway
// one-liner over the PostHog CSV and history.json each time. The arithmetic is
// fixed, so it lives here instead: snapshot de-duplication, platform weighting,
// times-reshared, and clicks-per-reshare. Judgement (which tier an item belongs
// in) stays with the human; this module only produces the numbers.
//
// Pure functions only — file reading and printing live in reshareReport.ts.

import { postedCount, parsePostedMarker } from "../buffer-post/sourceMarking";

// ============================================================================
// CSV
// ============================================================================

/**
 * Minimal RFC4180 parser: handles quoted fields, escaped `""`, and embedded
 * commas/newlines. PostHog quotes any path containing a comma.
 */
export function parseCsv(text: string): string[][] {
  const rows: string[][] = [];
  let row: string[] = [];
  let field = "";
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += c;
      }
      continue;
    }
    if (c === '"') {
      inQuotes = true;
    } else if (c === ",") {
      row.push(field);
      field = "";
    } else if (c === "\n") {
      row.push(field);
      rows.push(row);
      row = [];
      field = "";
    } else if (c !== "\r") {
      field += c;
    }
  }
  if (field !== "" || row.length > 0) {
    row.push(field);
    rows.push(row);
  }
  return rows.filter((r) => r.some((f) => f.trim() !== ""));
}

export interface EntryPathRow {
  snapshotDate: string;
  entryPath: string;
  utmSource: string;
  utmCampaign: string;
  sessions: number;
}

/** Map the entry-path CSV onto records, driven by its header row. */
export function toEntryPathRows(table: string[][]): EntryPathRow[] {
  if (table.length === 0) return [];
  const header = table[0].map((h) => h.trim());
  const col = (name: string) => header.indexOf(name);
  const [snap, pathCol, src, campaign, sessions] = [
    col("snapshot_date"),
    col("entry_path"),
    col("utm_source"),
    col("utm_campaign"),
    col("sessions"),
  ];
  if ([snap, pathCol, src, campaign, sessions].some((i) => i === -1)) {
    throw new Error(
      `entry-path CSV is missing expected columns; got: ${header.join(", ")}`,
    );
  }
  return table.slice(1).map((r) => ({
    snapshotDate: r[snap]?.trim() ?? "",
    entryPath: r[pathCol]?.trim() ?? "",
    utmSource: (r[src] ?? "").trim().toLowerCase(),
    utmCampaign: (r[campaign] ?? "").trim().toLowerCase(),
    sessions: Number(r[sessions] ?? 0) || 0,
  }));
}

// ============================================================================
// Paths
// ============================================================================

/** `/blog/foo/` and `https://…/blog/foo/?utm=…` both become `blog/foo`. */
export function normalizeContentPath(pathOrUrl: string): string | null {
  const withoutQuery = pathOrUrl.split(/[?#]/)[0];
  const m = /(?:^|\/)(blog|glossary|quiz)\/([a-z0-9_-]+)/i.exec(withoutQuery);
  if (!m) return null;
  return `${m[1].toLowerCase()}/${m[2].toLowerCase()}`;
}

// ============================================================================
// Reshare clicks
// ============================================================================

export const RESHARE_CAMPAIGN = "archive-reshare";

/**
 * Relative worth of a click by platform. LinkedIn is the main audience, so a
 * steady LinkedIn trickle outranks a one-off Mastodon spike.
 */
export const PLATFORM_WEIGHTS: Record<string, number> = {
  linkedin: 1.0,
  mastodon: 0.4,
  bluesky: 0.3,
};

/**
 * Keep only the newest snapshot for each (entry_path, utm_source).
 *
 * These are rolling 30-day snapshots appended over time, so consecutive rows
 * overlap by up to 29 days. Summing them all would multiply-count the same
 * sessions; the latest snapshot is one clean 30-day window per series.
 */
export function latestSnapshotPerSeries(rows: EntryPathRow[]): EntryPathRow[] {
  const newest = new Map<string, EntryPathRow>();
  for (const row of rows) {
    const key = `${row.entryPath}|${row.utmSource}`;
    const prior = newest.get(key);
    if (!prior || row.snapshotDate > prior.snapshotDate) newest.set(key, row);
  }
  return [...newest.values()];
}

export interface ClickTotals {
  weighted: number;
  bySource: Record<string, number>;
  snapshotDate: string;
}

/** Weighted reshare clicks per content path, from the deduped rows. */
export function weightedClicksByPath(
  rows: EntryPathRow[],
): Map<string, ClickTotals> {
  const reshares = latestSnapshotPerSeries(
    rows.filter((r) => r.utmCampaign === RESHARE_CAMPAIGN),
  );
  const totals = new Map<string, ClickTotals>();
  for (const row of reshares) {
    const contentPath = normalizeContentPath(row.entryPath);
    if (!contentPath) continue;
    const weight = PLATFORM_WEIGHTS[row.utmSource] ?? 0;
    const entry = totals.get(contentPath) ?? {
      weighted: 0,
      bySource: {},
      snapshotDate: row.snapshotDate,
    };
    entry.weighted += row.sessions * weight;
    entry.bySource[row.utmSource] =
      (entry.bySource[row.utmSource] ?? 0) + row.sessions;
    if (row.snapshotDate > entry.snapshotDate) {
      entry.snapshotDate = row.snapshotDate;
    }
    totals.set(contentPath, entry);
  }
  return totals;
}

// ============================================================================
// Times reshared
// ============================================================================

const QUEUE_LINE_WITH_URL =
  /^\s*-\s*\[(?: |x|X)\]\s*(.*?)\s*(https?:\/\/\S+)\s*$/;

/**
 * Times reshared per content path, read off the calendar's posted markers.
 *
 * Since the scheduler stamps these itself, the calendar is the reliable ledger
 * going forward; history.json only covers posts whose stored text happened to
 * carry the link.
 */
export function timesResharedFromCalendar(markdown: string): Map<string, number> {
  const counts = new Map<string, number>();
  for (const line of markdown.split("\n")) {
    const m = QUEUE_LINE_WITH_URL.exec(line);
    if (!m) continue;
    const contentPath = normalizeContentPath(m[2]);
    if (!contentPath) continue;
    const trailing = /\(([^()]*)\)\s*$/.exec(m[1]);
    const count = trailing ? postedCount(parsePostedMarker(trailing[1])) : 0;
    counts.set(contentPath, Math.max(counts.get(contentPath) ?? 0, count));
  }
  return counts;
}

export interface HistoryPost {
  posted?: string;
  linkedin?: string | null;
  mastodon?: string[] | null;
  bluesky?: string[] | null;
  engagement?: {
    linkedin?: {
      reactions?: number;
      comments?: number;
      engagementRate?: string;
    };
  } | null;
}

function postText(post: HistoryPost): string {
  return [post.linkedin, ...(post.mastodon ?? []), ...(post.bluesky ?? [])]
    .filter((t): t is string => typeof t === "string")
    .join(" ");
}

/** Content paths referenced by a post's stored text, deduped within the post. */
export function pathsInPost(post: HistoryPost): string[] {
  const text = postText(post);
  const found = new Set<string>();
  const re = /agilepainrelief\.com\/(blog|glossary|quiz)\/([a-z0-9_-]+)/gi;
  let m: RegExpExecArray | null;
  while ((m = re.exec(text)) !== null) {
    found.add(`${m[1].toLowerCase()}/${m[2].toLowerCase()}`);
  }
  return [...found];
}

export function timesResharedFromHistory(
  posts: HistoryPost[],
): Map<string, number> {
  const counts = new Map<string, number>();
  for (const post of posts) {
    for (const contentPath of pathsInPost(post)) {
      counts.set(contentPath, (counts.get(contentPath) ?? 0) + 1);
    }
  }
  return counts;
}

// ============================================================================
// Engagement
// ============================================================================

export interface Engagement {
  samples: number;
  avgEngagementRate: number;
  avgReactions: number;
  avgComments: number;
}

/** Parse history.json's `"7%"` engagement-rate strings. */
export function parseEngagementRate(value: string | undefined): number | null {
  if (typeof value !== "string") return null;
  const m = /^(-?\d+(?:\.\d+)?)\s*%$/.exec(value.trim());
  return m ? Number(m[1]) : null;
}

/** Average LinkedIn engagement per content path across its posts. */
export function engagementByPath(
  posts: HistoryPost[],
): Map<string, Engagement> {
  const acc = new Map<
    string,
    { rates: number[]; reactions: number[]; comments: number[] }
  >();
  for (const post of posts) {
    const li = post.engagement?.linkedin;
    if (!li) continue;
    for (const contentPath of pathsInPost(post)) {
      const bucket = acc.get(contentPath) ?? {
        rates: [],
        reactions: [],
        comments: [],
      };
      const rate = parseEngagementRate(li.engagementRate);
      if (rate !== null) bucket.rates.push(rate);
      if (typeof li.reactions === "number") bucket.reactions.push(li.reactions);
      if (typeof li.comments === "number") bucket.comments.push(li.comments);
      acc.set(contentPath, bucket);
    }
  }

  const mean = (xs: number[]) =>
    xs.length === 0 ? 0 : xs.reduce((a, b) => a + b, 0) / xs.length;

  const out = new Map<string, Engagement>();
  for (const [contentPath, b] of acc) {
    out.set(contentPath, {
      samples: Math.max(b.rates.length, b.reactions.length),
      avgEngagementRate: mean(b.rates),
      avgReactions: mean(b.reactions),
      avgComments: mean(b.comments),
    });
  }
  return out;
}

// ============================================================================
// The report
// ============================================================================

export interface ReportRow {
  contentPath: string;
  title: string;
  tier: string;
  weightedClicks: number;
  bySource: Record<string, number>;
  timesReshared: number;
  clicksPerReshare: number;
  engagement: Engagement | null;
  /** True when the numbers are too small to act on. */
  lowConfidence: boolean;
}

export interface QueueItem {
  contentPath: string;
  title: string;
  tier: string;
  posted: boolean;
}

const TIER_HEADING = /^#{2,4}\s*(TIER\s*\d[^\n]*)$/i;

/** Queue items with the tier heading they sit under. */
export function parseQueue(markdown: string): QueueItem[] {
  const items: QueueItem[] = [];
  let tier = "(untiered)";
  for (const line of markdown.split("\n")) {
    const heading = TIER_HEADING.exec(line.trim());
    if (heading) {
      tier = heading[1].trim();
      continue;
    }
    const m = /^\s*-\s*\[( |x|X)\]\s*(.*?)\s*(https?:\/\/\S+)\s*$/.exec(line);
    if (!m) continue;
    const contentPath = normalizeContentPath(m[3]);
    if (!contentPath) continue;
    items.push({
      contentPath,
      title: m[2].replace(/\s*\([^()]*\)\s*$/, "").trim(),
      tier,
      posted: m[1].toLowerCase() === "x",
    });
  }
  return items;
}

/** Below this many weighted clicks, differences are noise. */
export const LOW_CONFIDENCE_CLICKS = 5;

/**
 * Rank posted queue items by clicks-per-reshare.
 *
 * Dividing by times-reshared is what keeps this honest: raw sessions just
 * reward whatever went out most recently or most often.
 */
export function buildReport(input: {
  queue: QueueItem[];
  clicks: Map<string, ClickTotals>;
  calendarReshares: Map<string, number>;
  historyReshares: Map<string, number>;
  engagement: Map<string, Engagement>;
}): ReportRow[] {
  const rows: ReportRow[] = [];
  for (const item of input.queue) {
    if (!item.posted) continue;
    const clicks = input.clicks.get(item.contentPath);
    const weightedClicks = clicks?.weighted ?? 0;
    // The two ledgers are each incomplete; the larger is the better floor.
    const timesReshared = Math.max(
      input.calendarReshares.get(item.contentPath) ?? 0,
      input.historyReshares.get(item.contentPath) ?? 0,
      1,
    );
    rows.push({
      contentPath: item.contentPath,
      title: item.title,
      tier: item.tier,
      weightedClicks,
      bySource: clicks?.bySource ?? {},
      timesReshared,
      clicksPerReshare: weightedClicks / timesReshared,
      engagement: input.engagement.get(item.contentPath) ?? null,
      lowConfidence: weightedClicks < LOW_CONFIDENCE_CLICKS,
    });
  }
  return rows.sort(
    (a, b) =>
      b.clicksPerReshare - a.clicksPerReshare ||
      a.contentPath.localeCompare(b.contentPath),
  );
}

/**
 * Pages pulling reshare clicks that aren't queued at all — candidates to add.
 */
export function unqueuedWithClicks(
  clicks: Map<string, ClickTotals>,
  queue: QueueItem[],
): Array<{ contentPath: string; weighted: number }> {
  const queued = new Set(queue.map((q) => q.contentPath));
  return [...clicks.entries()]
    .filter(([contentPath]) => !queued.has(contentPath))
    .map(([contentPath, totals]) => ({
      contentPath,
      weighted: totals.weighted,
    }))
    .sort((a, b) => b.weighted - a.weighted);
}

