/**
 * Keep only the newest snapshot for each (entry_path, utm_source).
 *
 * These are rolling 30-day snapshots appended over time, so consecutive rows
 * overlap by up to 29 days. Summing them all would multiply-count the same
 * sessions; the latest snapshot is one clean 30-day window per series.
 */
export function latestSnapshotPerSeries(rows: EntryPathRow[]): EntryPathRow[] {
  const newest = new Map<string, EntryPathRow>();
  for (const row of rows) {
    const key = `${row.entryPath}|${row.utmSource}`;
    const prior = newest.get(key);
    if (!prior || row.snapshotDate > prior.snapshotDate) newest.set(key, row);
  }
  return [...newest.values()];
}

input.new_string:
const ISO_SNAPSHOT = /^\d{4}-\d{2}-\d{2}$/;

/** Rows whose snapshot window is unknown, so they can be reported not hidden. */
export function undatedRows(rows: EntryPathRow[]): EntryPathRow[] {
  return rows.filter((r) => !ISO_SNAPSHOT.test(r.snapshotDate));
}

/**
 * Keep only the newest snapshot for each (entry_path, utm_source).
 *
 * These are rolling 30-day snapshots appended over time, so consecutive rows
 * overlap by up to 29 days. Summing them all would multiply-count the same
 * sessions; the latest snapshot is one clean 30-day window per series.
 *
 * Rows with a non-ISO snapshot_date (PostHog emits a literal `unknown` for
 * some) are DROPPED. They have to be: their window is unknown, so they can be
 * neither compared nor safely added to a dated row. Note that comparing them as
 * plain strings would be actively wrong — `"unknown" > "2026-07-26"` — which
 * silently promotes a stale undated row over every real snapshot.
 */
export function latestSnapshotPerSeries(rows: EntryPathRow[]): EntryPathRow[] {
  const newest = new Map<string, EntryPathRow>();
  for (const row of rows) {
    if (!ISO_SNAPSHOT.test(row.snapshotDate)) continue;
    const key = `${row.entryPath}|${row.utmSource}`;
    const prior = newest.get(key);
    if (!prior || row.snapshotDate > prior.snapshotDate) newest.set(key, row);
  }
