import { describe, it, expect } from "vitest";
import {
  parseCsv,
  toEntryPathRows,
  normalizeContentPath,
  latestSnapshotPerSeries,
  weightedClicksByPath,
  timesResharedFromCalendar,
  timesResharedFromHistory,
  parseEngagementRate,
  engagementByPath,
  parseQueue,
  buildReport,
  unqueuedWithClicks,
  PLATFORM_WEIGHTS,
  EntryPathRow,
} from "./reshareMetrics";

describe("parseCsv", () => {
  it("parses a plain table", () => {
    expect(parseCsv("a,b\n1,2\n")).toEqual([
      ["a", "b"],
      ["1", "2"],
    ]);
  });

  it("handles quoted fields with commas and escaped quotes", () => {
    expect(parseCsv('a,b\n"x,y","he said ""hi"""\n')).toEqual([
      ["a", "b"],
      ["x,y", 'he said "hi"'],
    ]);
  });

  it("drops blank lines", () => {
    expect(parseCsv("a,b\n\n1,2\n\n")).toEqual([
      ["a", "b"],
      ["1", "2"],
    ]);
  });
});

const CSV = [
  "snapshot_date,entry_path,utm_source,utm_medium,utm_campaign,sessions",
  "2026-06-01,/blog/foo/,linkedin,,archive-reshare,4",
  "2026-07-01,/blog/foo/,linkedin,,archive-reshare,10",
  "2026-07-01,/blog/foo/,mastodon,,archive-reshare,5",
  "2026-07-01,/blog/bar/,linkedin,,archive-reshare,3",
  "2026-07-01,/blog/foo/,,,,900",
  "2026-07-01,/about/,linkedin,,archive-reshare,7",
  "",
].join("\n");

describe("toEntryPathRows", () => {
  it("maps columns by header name", () => {
    const rows = toEntryPathRows(parseCsv(CSV));
    expect(rows[0]).toEqual({
      snapshotDate: "2026-06-01",
      entryPath: "/blog/foo/",
      utmSource: "linkedin",
      utmCampaign: "archive-reshare",
      sessions: 4,
    });
  });

  it("throws rather than silently mis-reading an unexpected shape", () => {
    expect(() => toEntryPathRows(parseCsv("a,b\n1,2\n"))).toThrow(
      /missing expected columns/,
    );
  });
});

describe("normalizeContentPath", () => {
  it("normalizes paths and urls alike", () => {
    expect(normalizeContentPath("/blog/foo/")).toBe("blog/foo");
    expect(
      normalizeContentPath("https://agilepainrelief.com/glossary/bar/?utm_source=x"),
    ).toBe("glossary/bar");
    expect(normalizeContentPath("/about/")).toBeNull();
  });
});

describe("latestSnapshotPerSeries", () => {
  it("keeps the newest snapshot per (path, source) so overlapping windows are not summed", () => {
    const rows = toEntryPathRows(parseCsv(CSV)).filter(
      (r) => r.utmCampaign === "archive-reshare",
    );
    const deduped = latestSnapshotPerSeries(rows);
    const foo = deduped.filter(
      (r) => r.entryPath === "/blog/foo/" && r.utmSource === "linkedin",
    );
    expect(foo).toHaveLength(1);
    expect(foo[0].sessions).toBe(10); // 2026-07-01, not the older 4
  });
});

describe("weightedClicksByPath", () => {
  const clicks = weightedClicksByPath(toEntryPathRows(parseCsv(CSV)));

  it("weights LinkedIn above Mastodon", () => {
    // 10 linkedin * 1.0 + 5 mastodon * 0.4 = 12
    expect(clicks.get("blog/foo")!.weighted).toBeCloseTo(12);
    expect(clicks.get("blog/foo")!.bySource).toEqual({
      linkedin: 10,
      mastodon: 5,
    });
  });

  it("ignores rows that are not reshare-attributed", () => {
    // The 900-session untagged row for /blog/foo/ must not appear.
    expect(clicks.get("blog/foo")!.bySource.linkedin).toBe(10);
  });

  it("ignores non-content pages", () => {
    expect(clicks.has("about")).toBe(false);
  });

  it("uses the documented weights", () => {
    expect(PLATFORM_WEIGHTS).toEqual({
      linkedin: 1.0,
      mastodon: 0.4,
      bluesky: 0.3,
    });
  });
});

const CALENDAR = [
  "### TIER 1: GenAI Content",
  "- [x] Foo Post (2026-01-01, 2026-07-01) https://agilepainrelief.com/blog/foo/",
  "- [x] Bar Post (2025-08-15, 3x) https://agilepainrelief.com/blog/bar/",
  "- [ ] Baz Post https://agilepainrelief.com/blog/baz/",
  "### TIER 3: Scrum & Leadership",
  "- [x] Qux Entry (2026-02-02) https://agilepainrelief.com/glossary/qux/",
].join("\n");

describe("timesResharedFromCalendar", () => {
  it("counts explicit dates and the legacy Nx shorthand", () => {
    const counts = timesResharedFromCalendar(CALENDAR);
    expect(counts.get("blog/foo")).toBe(2);
    expect(counts.get("blog/bar")).toBe(3);
    expect(counts.get("blog/baz")).toBe(0);
  });
});

describe("timesResharedFromHistory", () => {
  it("counts one hit per post even when several platforms carry the link", () => {
    const counts = timesResharedFromHistory([
      {
        linkedin: "see https://agilepainrelief.com/blog/foo/?utm_source=linkedin",
        mastodon: ["also https://agilepainrelief.com/blog/foo/?utm_source=mastodon"],
      },
      { linkedin: "again https://agilepainrelief.com/blog/foo/" },
      { linkedin: "unrelated post with no link" },
    ]);
    expect(counts.get("blog/foo")).toBe(2);
  });
});

describe("parseEngagementRate", () => {
  it("reads the stored percentage strings", () => {
    expect(parseEngagementRate("7%")).toBe(7);
    expect(parseEngagementRate("0%")).toBe(0);
    expect(parseEngagementRate("2.5%")).toBe(2.5);
  });

  it("returns null for missing or malformed values", () => {
    expect(parseEngagementRate(undefined)).toBeNull();
    expect(parseEngagementRate("high")).toBeNull();
  });
});

describe("engagementByPath", () => {
  it("averages across a page's posts", () => {
    const e = engagementByPath([
      {
        linkedin: "https://agilepainrelief.com/blog/foo/",
        engagement: {
          linkedin: { reactions: 10, comments: 2, engagementRate: "4%" },
        },
      },
      {
        linkedin: "https://agilepainrelief.com/blog/foo/",
        engagement: {
          linkedin: { reactions: 20, comments: 4, engagementRate: "6%" },
        },
      },
    ]).get("blog/foo")!;
    expect(e.samples).toBe(2);
    expect(e.avgEngagementRate).toBe(5);
    expect(e.avgReactions).toBe(15);
    expect(e.avgComments).toBe(3);
  });
});

describe("parseQueue", () => {
  const queue = parseQueue(CALENDAR);

  it("captures the tier each item sits under", () => {
    expect(queue.find((q) => q.contentPath === "blog/foo")!.tier).toMatch(/TIER 1/);
    expect(queue.find((q) => q.contentPath === "glossary/qux")!.tier).toMatch(
      /TIER 3/,
    );
  });

  it("strips the posted marker from the title", () => {
    expect(queue.find((q) => q.contentPath === "blog/bar")!.title).toBe("Bar Post");
  });

  it("records posted state", () => {
    expect(queue.find((q) => q.contentPath === "blog/baz")!.posted).toBe(false);
  });
});

describe("buildReport", () => {
  const report = buildReport({
    queue: parseQueue(CALENDAR),
    clicks: weightedClicksByPath(toEntryPathRows(parseCsv(CSV))),
    calendarReshares: timesResharedFromCalendar(CALENDAR),
    historyReshares: new Map(),
    engagement: new Map(),
  });

  it("only reports items that have actually been posted", () => {
    expect(report.map((r) => r.contentPath)).not.toContain("blog/baz");
  });

  it("normalizes clicks by times reshared", () => {
    const foo = report.find((r) => r.contentPath === "blog/foo")!;
    expect(foo.timesReshared).toBe(2);
    expect(foo.clicksPerReshare).toBeCloseTo(6); // 12 weighted / 2 reshares
    const bar = report.find((r) => r.contentPath === "blog/bar")!;
    expect(bar.clicksPerReshare).toBeCloseTo(1); // 3 weighted / 3 reshares
  });

  it("ranks by clicks-per-reshare, not raw clicks", () => {
    expect(report[0].contentPath).toBe("blog/foo");
    expect(report[report.length - 1].clicksPerReshare).toBeLessThanOrEqual(
      report[0].clicksPerReshare,
    );
  });

  it("never divides by zero for an item with no recorded reshares", () => {
    const qux = report.find((r) => r.contentPath === "glossary/qux")!;
    expect(qux.timesReshared).toBe(1);
    expect(Number.isFinite(qux.clicksPerReshare)).toBe(true);
  });

  it("flags rows whose numbers are too small to act on", () => {
    expect(report.find((r) => r.contentPath === "blog/bar")!.lowConfidence).toBe(
      true,
    );
    expect(report.find((r) => r.contentPath === "blog/foo")!.lowConfidence).toBe(
      false,
    );
  });

  it("prefers whichever ledger records more reshares", () => {
    const withHistory = buildReport({
      queue: parseQueue(CALENDAR),
      clicks: weightedClicksByPath(toEntryPathRows(parseCsv(CSV))),
      calendarReshares: timesResharedFromCalendar(CALENDAR),
      historyReshares: new Map([["blog/foo", 4]]),
      engagement: new Map(),
    });
    expect(withHistory.find((r) => r.contentPath === "blog/foo")!.timesReshared).toBe(
      4,
    );
  });
});

describe("unqueuedWithClicks", () => {
  it("surfaces reshare-attributed pages missing from the queue", () => {
    const rows: EntryPathRow[] = toEntryPathRows(parseCsv(CSV));
    const clicks = weightedClicksByPath([
      ...rows,
      {
        snapshotDate: "2026-07-01",
        entryPath: "/glossary/unqueued/",
        utmSource: "linkedin",
        utmCampaign: "archive-reshare",
        sessions: 20,
      },
    ]);
    const missing = unqueuedWithClicks(clicks, parseQueue(CALENDAR));
    expect(missing[0]).toEqual({ contentPath: "glossary/unqueued", weighted: 20 });
  });
});

