    historyReshares: new Map(),
    engagement: new Map(),
  });

  it("only reports items that have actually been posted", () => {
    expect(report.map((r) => r.contentPath)).not.toContain("blog/baz");
  });

  it("normalizes clicks by times reshared", () => {
