// Reshare performance report for the quarterly queue tune.
//
//   npm run reshare-report                 # full ranked table
//   npm run reshare-report -- --top 10     # top and bottom 10 only
//   npm run reshare-report -- --json       # machine-readable
//
// Paths are cwd-relative: run from the agile-pain-relief-astro repo root.
//
// This produces the numbers only. Deciding what to promote, demote, or retire
// is a judgement call and stays with a human reading this table.

import * as fs from "fs";
import * as path from "path";
import {
  parseCsv,
  toEntryPathRows,
  weightedClicksByPath,
  timesResharedFromCalendar,
  timesResharedFromHistory,
  engagementByPath,
  parseQueue,
  buildReport,
  unqueuedWithClicks,
  LOW_CONFIDENCE_CLICKS,
  PLATFORM_WEIGHTS,
  ReportRow,
  HistoryPost,
} from "./reshareMetrics";

const ENTRY_PATH_CSV = path.resolve(
  "analytics/posthog/export-entry-path-by-utm-source.csv",
);
const HISTORY = path.resolve("analytics/history.json");
const CALENDAR = path.resolve(
  "social-media/planning/complete-social-media-calendar.md",
);

function readOrDie(file: string, what: string): string {
  if (!fs.existsSync(file)) {
    console.error(
      `reshare-report: ${what} not found at ${file}\n` +
        "Run this from the agile-pain-relief-astro repo root.",
    );
    process.exit(1);
  }
  return fs.readFileSync(file, "utf-8");
}

function pad(text: string, width: number): string {
  return text.length > width
    ? text.slice(0, width - 1) + "…"
    : text.padEnd(width);
}

function formatRow(row: ReportRow, rank: number): string {
  const sources = Object.entries(row.bySource)
    .sort((a, b) => b[1] - a[1])
    .map(([source, sessions]) => `${source[0].toUpperCase()}${sessions}`)
    .join(" ");
  const engagement = row.engagement
    ? `${row.engagement.avgEngagementRate.toFixed(1)}% r${row.engagement.avgReactions.toFixed(0)}`
    : "-";
  return [
    String(rank).padStart(3),
    pad(row.title, 44),
    row.clicksPerReshare.toFixed(1).padStart(7),
    row.weightedClicks.toFixed(1).padStart(7),
    String(row.timesReshared).padStart(3),
    pad(sources || "-", 14),
    pad(engagement, 11),
    row.lowConfidence ? "low-confidence" : "",
  ].join("  ");
}

function main(): void {
  const args = process.argv.slice(2);
  const asJson = args.includes("--json");
  const topIdx = args.indexOf("--top");
  const top = topIdx === -1 ? null : Number(args[topIdx + 1] || 10);

  const calendar = readOrDie(CALENDAR, "calendar");
  const csv = readOrDie(ENTRY_PATH_CSV, "PostHog entry-path export");
  const historyRaw = readOrDie(HISTORY, "history.json");

  const rows = toEntryPathRows(parseCsv(csv));
  const posts = (JSON.parse(historyRaw).posts ?? []) as HistoryPost[];
  const queue = parseQueue(calendar);
  const clicks = weightedClicksByPath(rows);

  const report = buildReport({
    queue,
    clicks,
    calendarReshares: timesResharedFromCalendar(calendar),
    historyReshares: timesResharedFromHistory(posts),
    engagement: engagementByPath(posts),
  });

  if (asJson) {
    console.log(
      JSON.stringify(
        { report, unqueued: unqueuedWithClicks(clicks, queue) },
        null,
        2,
      ),
    );
    return;
  }

  const weights = Object.entries(PLATFORM_WEIGHTS)
    .map(([k, v]) => `${k} ${v}`)
    .join(", ");
  const snapshots = [...clicks.values()].map((c) => c.snapshotDate).sort();

  console.log("=".repeat(110));
  console.log("Reshare performance (ranked by clicks per reshare)");
  console.log("=".repeat(110));
  console.log(
    `Attribution: utm_campaign=archive-reshare, latest 30-day snapshot per page+source` +
      (snapshots.length ? ` (newest ${snapshots[snapshots.length - 1]})` : ""),
  );
  console.log(`Weights: ${weights}. Posted queue items only: ${report.length}.`);
  console.log(
    `Rows under ${LOW_CONFIDENCE_CLICKS} weighted clicks are flagged low-confidence — don't act on them alone.\n`,
  );

  console.log(
    [
      "  #",
      pad("Title", 44),
      "clicks/".padStart(7),
      "weight".padStart(7),
      " re",
      pad("sessions", 14),
      pad("engagement", 11),
    ].join("  "),
  );
  console.log(
    ["  =", pad("", 44).replace(/ /g, "="), "reshare", " clicks", "  x", pad("", 14).replace(/ /g, "="), pad("", 11).replace(/ /g, "=")].join("  "),
  );

  const shown =
    top === null
      ? report
      : [...report.slice(0, top), ...report.slice(-top)].filter(
          (row, i, all) => all.indexOf(row) === i,
        );
  if (top !== null && report.length > shown.length) {
    const head = report.slice(0, top);
    for (const [i, row] of head.entries()) console.log(formatRow(row, i + 1));
    console.log(`      … ${report.length - shown.length} rows omitted (--top ${top}) …`);
    for (const row of report.slice(-top)) {
      console.log(formatRow(row, report.indexOf(row) + 1));
    }
  } else {
    for (const [i, row] of report.entries()) console.log(formatRow(row, i + 1));
  }

  const noClicks = report.filter((r) => r.weightedClicks === 0);
  if (noClicks.length > 0) {
    console.log(
      `\n${noClicks.length} posted item(s) have no reshare-attributed sessions in the latest snapshot.`,
    );
  }

  const missing = unqueuedWithClicks(clicks, queue);
  if (missing.length > 0) {
    console.log("\nPulling reshare clicks but not in the queue:");
    for (const m of missing.slice(0, 15)) {
      console.log(`  ${m.weighted.toFixed(1).padStart(7)}  ${m.contentPath}`);
    }
  }
  console.log("=".repeat(110));
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

