describe("slotDate", () => {
  it("uses the Eastern calendar date, which is what the queues record", () => {
    expect(slotDate("2026-05-29T13:30:00-04:00")).toBe("2026-05-29");
    expect(slotDate("2026-05-29T10:00:00-04:00")).toBe("2026-05-29");
  });

  it("does not roll a late-evening ET slot into the next UTC day", () => {
    // 2026-05-30T02:00Z is still 2026-05-29 in New York.
    expect(slotDate("2026-05-30T02:00:00Z")).toBe("2026-05-29");
  });

  it("handles a standard-time (EST) slot", () => {
    expect(slotDate("2026-01-15T10:00:00-05:00")).toBe("2026-01-15");
  });

  it("stays on the ET date regardless of the machine's timezone offset", () => {
    // Same instant expressed two ways must yield the same queue date.
    expect(slotDate("2026-07-27T14:00:00Z")).toBe(
      slotDate("2026-07-27T10:00:00-04:00"),
    );
  });
});
EOF
