describe("SourceMarker", () => {
  const CALENDAR = [
    "### TIER 1",
    "- [ ] Some Post https://agilepainrelief.com/blog/some-post/",
    "- [x] Other Post (2026-01-01) https://agilepainrelief.com/blog/other-post/",
  ].join("\n");
  const SEEDS = [
    "Senior devs felt 20% faster using AI. METR measured 19% slower.",
    "",
    "Twelve questions:",
    "-",
    "Security defects in AI-authored code: roughly 1.57x.",
    "-",
  ].join("\n");

  function sandbox() {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), "marker-"));
    const calendar = path.join(dir, "calendar.md");
    const seeds = path.join(dir, "seeds.md");
    fs.writeFileSync(calendar, CALENDAR);
    fs.writeFileSync(seeds, SEEDS);
    return { dir, calendar, seeds };
  }

  it("checks off the calendar item matching the entry url", () => {
    const { calendar, seeds } = sandbox();
    const marker = new SourceMarker(true, calendar, seeds);
    marker.mark(makeEntry({ url: BLOG_URL }), "2026-07-27");
    expect(fs.readFileSync(calendar, "utf-8")).toContain(
      "- [x] Some Post (2026-07-27) https://agilepainrelief.com/blog/some-post/",
    );
    expect(marker.notes).toEqual([]);
  });

  it("marks the quiz seed named by the entry's seed field", () => {
    const { calendar, seeds } = sandbox();
    const marker = new SourceMarker(true, calendar, seeds);
    marker.mark(
      makeEntry({
        url: "https://agilepainrelief.com/quiz/ai-failure-modes/",
        seed: "Security defects in AI-authored code",
      }),
      "2026-07-27",
    );
    expect(fs.readFileSync(seeds, "utf-8")).toContain(
      "[POSTED 2026-07-27]\nSecurity defects in AI-authored code",
    );
    expect(marker.notes).toEqual([]);
  });

  it("does not look for a quiz url in the calendar queue", () => {
    const { calendar, seeds } = sandbox();
    const marker = new SourceMarker(true, calendar, seeds);
    marker.mark(
      makeEntry({ url: "https://agilepainrelief.com/quiz/ai-failure-modes/" }),
      "2026-07-27",
    );
    expect(fs.readFileSync(calendar, "utf-8")).toBe(CALENDAR);
    expect(marker.notes).toEqual([]);
  });

  it("writes nothing when disabled (dry run / --no-mark)", () => {
    const { calendar, seeds } = sandbox();
    const marker = new SourceMarker(false, calendar, seeds);
    marker.mark(makeEntry({ url: BLOG_URL, seed: "Security defects" }), "2026-07-27");
    expect(fs.readFileSync(calendar, "utf-8")).toBe(CALENDAR);
    expect(fs.readFileSync(seeds, "utf-8")).toBe(SEEDS);
  });

  it("reports an unmatched seed instead of editing the wrong block", () => {
    const { calendar, seeds } = sandbox();
    const marker = new SourceMarker(true, calendar, seeds);
    marker.mark(
      makeEntry({ url: BLOG_URL, seed: "wording that is not in any block" }),
      "2026-07-27",
    );
    expect(fs.readFileSync(seeds, "utf-8")).toBe(SEEDS);
    expect(marker.notes.join(" ")).toContain("not-found");
  });

  it("reports a missing planning file rather than throwing mid-batch", () => {
    const { dir } = sandbox();
    const marker = new SourceMarker(
      true,
      path.join(dir, "nope.md"),
      path.join(dir, "nope-seeds.md"),
    );
    expect(() => marker.mark(makeEntry({ url: BLOG_URL }), "2026-07-27")).not.toThrow();
    expect(marker.notes.join(" ")).toContain("not found");
  });

  it("is idempotent across a re-run", () => {
    const { calendar, seeds } = sandbox();
    new SourceMarker(true, calendar, seeds).mark(
      makeEntry({ url: BLOG_URL }),
      "2026-07-27",
    );
    const afterFirst = fs.readFileSync(calendar, "utf-8");
    const second = new SourceMarker(true, calendar, seeds);
    second.mark(makeEntry({ url: BLOG_URL }), "2026-07-27");
    expect(fs.readFileSync(calendar, "utf-8")).toBe(afterFirst);
    expect(second.notes.join(" ")).toContain("unchanged");
  });
});
EOF
