// hashtags fit, and "never invent stats" are not mechanizable and are not here.
//
// Pure functions only.

export type Severity = "error" | "warning";

export interface ContentIssue {
  severity: Severity;
  rule: string;
  network?: string;
  message: string;
}

/** Structural shape of a batch entry, declared here to avoid an import cycle. */
export interface EntryLike {
  linkedin: string;
  mastodon: string | string[];
  bluesky: string | string[];
  url?: string;
  image?: string;
}

type Network = "LinkedIn" | "Mastodon" | "Bluesky";

const NETWORKS: Network[] = ["LinkedIn", "Mastodon", "Bluesky"];

export const STANDARD_HASHTAG = "#AIinSoftwareDevelopment";

/** Per-network hashtag count, inclusive [min, max]. */
export const HASHTAG_RANGE: Record<Network, [number, number]> = {
  LinkedIn: [2, 4],
  Mastodon: [2, 3],
  Bluesky: [2, 2],
};

/** Hard cap on thread parts. "Never 4" for Mastodon; Bluesky 2-3 max. */
export const MAX_THREAD_PARTS: Record<"Mastodon" | "Bluesky", number> = {
  Mastodon: 3,
  Bluesky: 3,
};

/** Above this, Mastodon threading is discouraged but allowed. */
const PREFERRED_MASTODON_PARTS = 2;

function parts(value: string | string[]): string[] {
  return Array.isArray(value) ? value : [value];
}

function networkParts(entry: EntryLike, network: Network): string[] {
  if (network === "LinkedIn") return [entry.linkedin];
  return parts(network === "Mastodon" ? entry.mastodon : entry.bluesky);
}

// ============================================================================
// Individual rules
// ============================================================================

const EM_DASH = /—/;
const NBSP = / /;
const HASHTAG = /#[A-Za-z0-9_]+/g;

export function hasEmDash(text: string): boolean {
  return EM_DASH.test(text);
}

export function hasNbsp(text: string): boolean {
  return NBSP.test(text);
}

export function countHashtags(text: string): number {
  return (text.match(HASHTAG) || []).length;
}

/** Hashtags across every part of a network — they may sit on the final part. */
function hashtagsAcross(partsList: string[]): number {
  return partsList.reduce((n, part) => n + countHashtags(part), 0);
}

const UTM_PREFILLED = /[?&]utm_/i;

// ============================================================================
// Entry-level checks
// ============================================================================

export function checkEntry(entry: EntryLike): ContentIssue[] {
  const issues: ContentIssue[] = [];

  for (const network of NETWORKS) {
    const partsList = networkParts(entry, network);

    partsList.forEach((part, i) => {
      const where =
        partsList.length > 1 ? `${network} part ${i + 1}` : network;
      if (hasEmDash(part)) {
        issues.push({
          severity: "error",
          rule: "em-dash",
          network,
          message: `${where} contains an em dash (U+2014). Use a colon, comma, semicolon, or restructure.`,
        });
      }
      if (hasNbsp(part)) {
        issues.push({
          severity: "error",
          rule: "nbsp",
          network,
          message: `${where} contains a non-breaking space (U+00A0). Use an ASCII space.`,
        });
      }
    });

    const [min, max] = HASHTAG_RANGE[network];
    const tags = hashtagsAcross(partsList);
    if (tags < min || tags > max) {
      issues.push({
        severity: "warning",
        rule: "hashtag-count",
        network,
        message: `${network} has ${tags} hashtag(s); the convention is ${min}${max === min ? "" : `-${max}`}.`,
      });
    }

    if (!partsList.some((part) => part.includes(STANDARD_HASHTAG))) {
      issues.push({
        severity: "warning",
        rule: "standard-hashtag",
        network,
        message: `${network} is missing ${STANDARD_HASHTAG}, which goes on every post.`,
      });
    }
  }

  for (const network of ["Mastodon", "Bluesky"] as const) {
    const count = networkParts(entry, network).length;
    const cap = MAX_THREAD_PARTS[network];
    if (count > cap) {
      issues.push({
        severity: "error",
        rule: "thread-length",
        network,
        message: `${network} thread has ${count} parts; the cap is ${cap}. Tighten the earlier parts instead.`,
      });
    } else if (network === "Mastodon" && count > PREFERRED_MASTODON_PARTS) {
      issues.push({
        severity: "warning",
        rule: "thread-length",
        network,
        message: `Mastodon thread has ${count} parts; 1-2 is preferred at its 500-char limit.`,
      });
    }
  }

  if (entry.url && UTM_PREFILLED.test(entry.url)) {
    issues.push({
      severity: "error",
      rule: "prefilled-utm",
      message:
        "`url` already carries utm_ params. The pipeline appends per-network UTM, so a pre-filled URL locks every network to one source.",
    });
  }

  return issues;
}

// ============================================================================
// Batch-level checks
// ============================================================================

/**
 * Buffer's duplicate detection matches on shared image assets, so two entries
 * pointing at the same image URL means the second post is silently skipped.
 */
export function checkBatchImages(entries: EntryLike[]): ContentIssue[] {
  const seen = new Map<string, number>();
  const issues: ContentIssue[] = [];
  entries.forEach((entry, i) => {
    const image = entry.image?.trim();
    if (!image) return;
    const first = seen.get(image);
    if (first !== undefined) {
      issues.push({
        severity: "error",
        rule: "duplicate-image",
        message: `post ${i + 1} reuses the image URL from post ${first + 1}. Buffer dedups on shared image assets and would skip this post; give each entry a distinct image or "".`,
      });
      return;
    }
    seen.set(image, i);
  });
  return issues;
}

export function checkBatch(entries: EntryLike[]): ContentIssue[][] {
  return entries.map((entry) => checkEntry(entry));
}

