import { describe, it, expect } from "vitest";
import {
  hasEmDash,
  hasNbsp,
  countHashtags,
  checkEntry,
  checkBatchImages,
  EntryLike,
} from "./contentRules";

const EM_DASH = "—";
const NBSP = " ";

/** A clean entry: 2 hashtags per network including the standard one. */
function makeEntry(overrides: Partial<EntryLike> = {}): EntryLike {
  const tags = "#AIinSoftwareDevelopment #Agile";
  return {
    linkedin: `LinkedIn body.\n\n${tags}`,
    mastodon: `Mastodon body.\n\n${tags}`,
    bluesky: `Bluesky body.\n\n${tags}`,
    ...overrides,
  };
}

const errors = (e: EntryLike) =>
  checkEntry(e).filter((i) => i.severity === "error");
const warnings = (e: EntryLike) =>
  checkEntry(e).filter((i) => i.severity === "warning");

describe("primitives", () => {
  it("detects an em dash but not a hyphen or en dash", () => {
    expect(hasEmDash(`a ${EM_DASH} b`)).toBe(true);
    expect(hasEmDash("a - b")).toBe(false);
    expect(hasEmDash("a – b")).toBe(false);
  });

  it("detects U+00A0 but not an ordinary space", () => {
    expect(hasNbsp(`a${NBSP}b`)).toBe(true);
    expect(hasNbsp("a b")).toBe(false);
  });

  it("counts hashtags", () => {
    expect(countHashtags("no tags here")).toBe(0);
    expect(countHashtags("#Agile and #Scrum")).toBe(2);
    expect(countHashtags("#AIinSoftwareDevelopment")).toBe(1);
  });
});

describe("a clean entry", () => {
  it("produces no issues at all", () => {
    expect(checkEntry(makeEntry())).toEqual([]);
  });
});

describe("hard errors", () => {
  it("flags an em dash in any network", () => {
    const issues = errors(
      makeEntry({ linkedin: `Body ${EM_DASH} more.\n\n#AIinSoftwareDevelopment #Agile` }),
    );
    expect(issues).toHaveLength(1);
    expect(issues[0].rule).toBe("em-dash");
    expect(issues[0].network).toBe("LinkedIn");
  });

  it("names the offending thread part", () => {
    const issues = errors(
      makeEntry({
        bluesky: ["Root.", `Reply ${EM_DASH} here.\n\n#AIinSoftwareDevelopment #Agile`],
      }),
    );
    expect(issues[0].message).toContain("Bluesky part 2");
  });

  it("flags a non-breaking space", () => {
    const issues = errors(
      makeEntry({ mastodon: `Body${NBSP}here.\n\n#AIinSoftwareDevelopment #Agile` }),
    );
    expect(issues.map((i) => i.rule)).toEqual(["nbsp"]);
  });

  it("blocks a 4-part thread but allows 3", () => {
    const four = ["a", "b", "c", "d #AIinSoftwareDevelopment #Agile"];
    expect(errors(makeEntry({ bluesky: four })).map((i) => i.rule)).toContain(
      "thread-length",
    );
    const three = ["a", "b", "c #AIinSoftwareDevelopment #Agile"];
    expect(errors(makeEntry({ bluesky: three }))).toEqual([]);
  });

  it("rejects a pre-filled UTM on the url field", () => {
    const issues = errors(
      makeEntry({
        url: "https://agilepainrelief.com/blog/x/?utm_source=linkedin",
      }),
    );
    expect(issues.map((i) => i.rule)).toEqual(["prefilled-utm"]);
  });

  it("accepts a clean url", () => {
    expect(errors(makeEntry({ url: "https://agilepainrelief.com/blog/x/" }))).toEqual(
      [],
    );
  });
});

describe("warnings (never blocking)", () => {
  it("flags too few hashtags", () => {
    const issues = warnings(makeEntry({ bluesky: "Body with #Agile only." }));
    expect(issues.map((i) => i.rule)).toContain("hashtag-count");
    expect(issues.map((i) => i.rule)).toContain("standard-hashtag");
  });

  it("flags too many hashtags on Bluesky, which allows exactly 2", () => {
    const issues = warnings(
      makeEntry({ bluesky: "Body #AIinSoftwareDevelopment #Agile #Scrum" }),
    );
    const tag = issues.find((i) => i.rule === "hashtag-count");
    expect(tag!.message).toContain("3 hashtag(s)");
    expect(tag!.message).toContain("2");
  });

  it("allows LinkedIn up to 4", () => {
    const four = "#AIinSoftwareDevelopment #Agile #Scrum #Leadership";
    expect(
      warnings(makeEntry({ linkedin: `Body.\n\n${four}` })).map((i) => i.rule),
    ).not.toContain("hashtag-count");
  });

  it("counts hashtags across all parts of a thread, since they sit on the last", () => {
    const issues = warnings(
      makeEntry({ bluesky: ["Root with no tags.", "#AIinSoftwareDevelopment #Agile"] }),
    );
    expect(issues.map((i) => i.rule)).not.toContain("hashtag-count");
  });

  it("prefers 1-2 Mastodon parts but does not block 3", () => {
    const issues = checkEntry(
      makeEntry({ mastodon: ["a", "b", "c #AIinSoftwareDevelopment #Agile"] }),
    );
    const thread = issues.filter((i) => i.rule === "thread-length");
    expect(thread).toHaveLength(1);
    expect(thread[0].severity).toBe("warning");
  });

  it("never reports a warning as an error", () => {
    const issues = checkEntry(makeEntry({ bluesky: "Body with no tags." }));
    expect(issues.every((i) => i.severity === "warning")).toBe(true);
  });
});

describe("checkBatchImages", () => {
  it("passes when every image is distinct or empty", () => {
    expect(
      checkBatchImages([
        makeEntry({ image: "https://x/a.png" }),
        makeEntry({ image: "https://x/b.png" }),
        makeEntry({ image: "" }),
        makeEntry(),
      ]),
    ).toEqual([]);
  });

  it("flags a reused image URL, naming both posts", () => {
    const issues = checkBatchImages([
      makeEntry({ image: "https://x/a.png" }),
      makeEntry({ image: "https://x/a.png" }),
    ]);
    expect(issues).toHaveLength(1);
    expect(issues[0].severity).toBe("error");
    expect(issues[0].message).toContain("post 2");
    expect(issues[0].message).toContain("post 1");
  });

  it("does not treat repeated empty images as duplicates", () => {
    expect(
      checkBatchImages([makeEntry({ image: "" }), makeEntry({ image: "  " })]),
    ).toEqual([]);
  });
});

