export interface PreflightIssue {
  index: number;
  snippet: string;
  message: string;
  severity: Severity;
}

/**
 * Every check that runs before a batch is scheduled.
 *
 * Errors block. Warnings are conventions with real exceptions (hashtag counts,
 * thread-length preferences) and are reported without stopping the run — see
 * `contentRules.ts` for why the line is drawn there.
 */
export function preflight(entries: BatchEntry[]): PreflightIssue[] {
  const issues: PreflightIssue[] = [];
  const add = (index: number, tag: string, message: string, severity: Severity) =>
    issues.push({ index, snippet: tag, message, severity });

  for (const [i, entry] of entries.entries()) {
    const tag = snippet(entry);
    const { content, errors: prepErrors } = prepareContent(entry);
    for (const msg of prepErrors) add(i + 1, tag, msg, "error");
    for (const err of validateCharacterLimits(content)) {
      add(
        i + 1,
        tag,
        `${err.network} over ${err.limit} chars (got ${err.effectiveLength} after per-network URL counting)`,
        "error",
      );
    }
    for (const msg of validateNoLinkInComments(content)) {
      add(i + 1, tag, msg, "error");
    }
    for (const issue of checkEntry(entry)) {
      add(i + 1, tag, issue.message, issue.severity);
    }
  }

  // Batch-level: image reuse can only be seen across entries.
  for (const issue of checkBatchImages(entries)) {
    add(0, "batch", issue.message, issue.severity);
  }
  return issues;
}

export const blockingIssues = (issues: PreflightIssue[]) =>
  issues.filter((i) => i.severity === "error");

