// Validate an evergreen batch JSON file without touching Buffer.
//
// This is the SAME pre-flight the scheduler runs (`preflight` in batchPost.ts),
// exposed as a standalone command so the authoring skills can check a file they
// just wrote instead of re-implementing the rules. There is exactly one
// implementation of "does this post fit"; this entry point is a thin shell over
// it. No token, no network, no writes.
//
//   npm run validate -- --file analytics/social-media-content-evergreen/x.json
//
// Paths are resolved relative to cwd, matching `npm run batch`.

import * as path from "path";
import {
  CHAR_LIMITS,
  URL_COUNT_LENGTH,
  calculateEffectiveLength,
  NetworkType,
} from "./bufferPost";
import {
  BatchEntry,
  readBatchFile,
  preflight,
  prepareContent,
} from "./batchPost";

/** Worst (largest) effective part length on a network, after the url is appended. */
function worstPart(parts: string[], network: NetworkType): number {
  return Math.max(
    ...parts.map((part) =>
      calculateEffectiveLength(part, URL_COUNT_LENGTH[network]),
    ),
  );
}

interface EntryReport {
  index: number;
  linkedin: number;
  mastodon: number;
  bluesky: number;
  mastodonParts: number;
  blueskyParts: number;
}

/**
 * Per-entry character usage, measured on the composed content (url + UTM
 * already appended to the last part) exactly as the scheduler would send it.
 */
export function reportEntry(entry: BatchEntry, index: number): EntryReport {
  const { content } = prepareContent(entry);
  return {
    index,
    linkedin: worstPart([content.linkedin], "LinkedIn"),
    mastodon: worstPart(content.mastodon, "Mastodon"),
    bluesky: worstPart(content.bluesky, "Bluesky"),
    mastodonParts: content.mastodon.length,
    blueskyParts: content.bluesky.length,
  };
}

function parseArgs(): string {
  const args = process.argv.slice(2);
  const fileIdx = args.indexOf("--file");
  if (fileIdx === -1 || !args[fileIdx + 1]) {
    console.error("Usage: npm run validate -- --file <path-to-batch.json>");
    process.exit(1);
  }
  return path.resolve(args[fileIdx + 1]);
}

function main(): void {
  const file = parseArgs();
  const entries = readBatchFile(file);
  console.log(`Validating ${entries.length} entr(ies) in ${file}\n`);

  const issues = preflight(entries);
  const failed = new Set(issues.map((i) => i.index));

  for (const [i, entry] of entries.entries()) {
    const r = reportEntry(entry, i + 1);
    const status = failed.has(i + 1) ? "FAIL" : "ok";
    console.log(
      `Post ${String(i + 1).padStart(2)}: ` +
        `LI=${r.linkedin}/${CHAR_LIMITS.LinkedIn} ` +
        `MS=${r.mastodon}/${CHAR_LIMITS.Mastodon}(${r.mastodonParts}p) ` +
        `BS=${r.bluesky}/${CHAR_LIMITS.Bluesky}(${r.blueskyParts}p) ` +
        status,
    );
  }

  if (issues.length === 0) {
    console.log("\nAll entries passed pre-flight.");
    return;
  }

  console.error(`\n${issues.length} validation error(s):`);
  for (const issue of issues) {
    console.error(`  • post ${issue.index} ("${issue.snippet}") — ${issue.message}`);
  }
  process.exit(1);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

