// Validate an evergreen batch JSON file without touching Buffer.
//
// This is the SAME pre-flight the scheduler runs (`preflight` in batchPost.ts),
// exposed as a standalone command so the authoring skills can check a file they
// just wrote instead of re-implementing the rules. There is exactly one
// implementation of "does this post fit"; this entry point is a thin shell over
// it. No token, no network, no writes.
//
//   npm run validate -- --file analytics/social-media-content-evergreen/x.json
//
// Paths are resolved relative to cwd, matching `npm run batch`.

import * as path from "path";
import {
  CHAR_LIMITS,
  URL_COUNT_LENGTH,
  calculateEffectiveLength,
  NetworkType,
} from "./bufferPost";
import {
  BatchEntry,
  readBatchFile,
  blockingIssues,
  preflight,
  prepareContent,
} from "./batchPost";

/** Worst (largest) effective part length on a network, after the url is appended. */
function worstPart(parts: string[], network: NetworkType): number {
  return Math.max(
    ...parts.map((part) =>
      calculateEffectiveLength(part, URL_COUNT_LENGTH[network]),
    ),
  );
}

interface EntryReport {
  index: number;
  linkedin: number;
  mastodon: number;
  bluesky: number;
  mastodonParts: number;
  blueskyParts: number;
}

/**
 * Per-entry character usage, measured on the composed content (url + UTM
 * already appended to the last part) exactly as the scheduler would send it.
 */
export function reportEntry(entry: BatchEntry, index: number): EntryReport {
  const { content } = prepareContent(entry);
  return {
    index,
    linkedin: worstPart([content.linkedin], "LinkedIn"),
    mastodon: worstPart(content.mastodon, "Mastodon"),
    bluesky: worstPart(content.bluesky, "Bluesky"),
    mastodonParts: content.mastodon.length,
    blueskyParts: content.bluesky.length,
  };
}

// ============================================================================
// Single-post (adapt) path
// ============================================================================

const TEMP_DIR = path.resolve("social-media", "temp");

/**
 * Validate `social-media/temp/` — the files `npm run post` reads.
 *
 * Same rules as the batch path, with one difference that comes from the format:
 * here the link lives inline in the body rather than in a `url` field, so an
 * inline URL is expected rather than a conflict.
 */
function validateAdaptPath(): number {
  const files = {
    linkedin: path.join(TEMP_DIR, "linkedin.txt"),
    mastodon: path.join(TEMP_DIR, "mastodon.json"),
    bluesky: path.join(TEMP_DIR, "bluesky.json"),
  };
  for (const [name, file] of Object.entries(files)) {
    if (!fs.existsSync(file)) {
      console.error(
        `validate: ${name} not found at ${file}\n` +
          "Run from the agile-pain-relief-astro repo root, or pass --file for a batch.",
      );
      return 1;
    }
  }

  const linkedin = fs.readFileSync(files.linkedin, "utf-8").trim();
  const readParts = (file: string, name: string): string[] => {
    const data = JSON.parse(fs.readFileSync(file, "utf-8"));
    if (!Array.isArray(data.parts) || data.parts.length === 0) {
      throw new Error(`${name} must be { "parts": ["..."] } with at least one part`);
    }
    return data.parts;
  };
  const mastodon = readParts(files.mastodon, "mastodon.json");
  const bluesky = readParts(files.bluesky, "bluesky.json");

  // Mirror what bufferPost does before it validates: UTM the inline links.
  const content = {
    linkedin: addUtmParamsToParts([linkedin], "LinkedIn")[0],
    mastodon: addUtmParamsToParts(mastodon, "Mastodon"),
    bluesky: addUtmParamsToParts(bluesky, "Bluesky"),
  };

  console.log(`Validating single-post content in ${TEMP_DIR}\n`);
  console.log(
    `  LinkedIn=${worstPart([content.linkedin], "LinkedIn")}/${CHAR_LIMITS.LinkedIn}  ` +
      `Mastodon=${worstPart(content.mastodon, "Mastodon")}/${CHAR_LIMITS.Mastodon}(${content.mastodon.length}p)  ` +
      `Bluesky=${worstPart(content.bluesky, "Bluesky")}/${CHAR_LIMITS.Bluesky}(${content.bluesky.length}p)`,
  );

  const errors: string[] = [];
  const warnings: string[] = [];
  for (const err of validateCharacterLimits(content)) {
    errors.push(
      `${err.network} part ${err.partIndex} over ${err.limit} chars (got ${err.effectiveLength})`,
    );
  }
  for (const msg of validateNoLinkInComments(content)) errors.push(msg);
  // Content rules run on the authored text, before UTM is appended.
  for (const issue of checkEntry({ linkedin, mastodon, bluesky })) {
    (issue.severity === "error" ? errors : warnings).push(issue.message);
  }

  // Staleness: adapted files older than the source mean the adapt step didn't rerun.
  const mtime = (f: string) => fs.statSync(f).mtimeMs;
  for (const name of ["mastodon", "bluesky"] as const) {
    if (mtime(files.linkedin) - mtime(files[name]) > 60_000) {
      warnings.push(
        `${name}.json is older than linkedin.txt — the adaptation may be stale (npm run post refuses to send this).`,
      );
    }
  }

  if (warnings.length > 0) {
    console.log(`\n${warnings.length} warning(s):`);
    for (const w of warnings) console.log(`  • ${w}`);
  }
  if (errors.length > 0) {
    console.error(`\n${errors.length} error(s):`);
    for (const e of errors) console.error(`  • ${e}`);
    return 1;
  }
  console.log("\nPassed. `npm run post` would accept this content.");
  return 0;
}

function parseArgs(): string | null {
  const args = process.argv.slice(2);
  const fileIdx = args.indexOf("--file");
  if (fileIdx === -1) return null; // no --file: validate the adapt path
  if (!args[fileIdx + 1]) {
    console.error(
      "Usage: npm run validate [-- --file <path-to-batch.json>]\n" +
        "  with --file : validate an evergreen batch JSON\n" +
        "  without     : validate social-media/temp/ (the single-post path)",
    );
    process.exit(1);
  }
  return path.resolve(args[fileIdx + 1]);
}

function main(): void {
  const file = parseArgs();
  const entries = readBatchFile(file);
  console.log(`Validating ${entries.length} entr(ies) in ${file}\n`);

  const issues = preflight(entries);
  const blocking = blockingIssues(issues);
  const warnings = issues.filter((i) => i.severity === "warning");
  const failed = new Set(blocking.map((i) => i.index));
  const warned = new Set(warnings.map((i) => i.index));

  for (const [i, entry] of entries.entries()) {
    const r = reportEntry(entry, i + 1);
    const status = failed.has(i + 1)
      ? "FAIL"
      : warned.has(i + 1)
        ? "warn"
        : "ok";
    console.log(
      `Post ${String(i + 1).padStart(2)}: ` +
        `LI=${r.linkedin}/${CHAR_LIMITS.LinkedIn} ` +
        `MS=${r.mastodon}/${CHAR_LIMITS.Mastodon}(${r.mastodonParts}p) ` +
        `BS=${r.bluesky}/${CHAR_LIMITS.Bluesky}(${r.blueskyParts}p) ` +
        status,
    );
  }

  if (warnings.length > 0) {
    console.log(`\n${warnings.length} convention warning(s) — will not block posting:`);
    for (const issue of warnings) {
      console.log(`  • post ${issue.index} ("${issue.snippet}") — ${issue.message}`);
    }
  }

  if (blocking.length === 0) {
    console.log(
      warnings.length > 0
        ? "\nNo blocking errors. Batch would post."
        : "\nAll entries passed pre-flight.",
    );
    return;
  }

  console.error(`\n${blocking.length} validation error(s):`);
  for (const issue of blocking) {
    console.error(`  • post ${issue.index} ("${issue.snippet}") — ${issue.message}`);
  }
  process.exit(1);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

